const https = require('https');
const rpc = (method, params) => new Promise((resolve, reject) => {
  const body = JSON.stringify({jsonrpc:'2.0', id:1, method, params});
  const req = https.request('https://ethereum.publicnode.com', {method:'POST', headers:{'content-type':'application/json','content-length':Buffer.byteLength(body)}, timeout:15000}, res => {
    let data=''; res.on('data', c => data += c); res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('timeout', () => { req.destroy(new Error('timeout')); });
  req.on('error', reject); req.write(body); req.end();
});
const token='0xce4a5d11fad8f04d76eb65a588dc6a2e2a734255';
const transfer='0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef';
const addrFromTopic=t=>'0x'+t.slice(26).toLowerCase();
const fmt=v=>Number(v/10n**14n)/10000;
(async()=>{
 const latest = BigInt((await rpc('eth_blockNumber', [])).result);
 const from = latest - 1200n;
 const res = await rpc('eth_getLogs', [{fromBlock:'0x'+from.toString(16), toBlock:'0x'+latest.toString(16), address:token, topics:[transfer]}]);
 if (res.error) throw new Error(JSON.stringify(res.error));
 const logs = res.result;
 const counts = new Map(), net = new Map(), txs = new Set();
 let mint=0n, total=0n;
 for (const l of logs) {
   const f=addrFromTopic(l.topics[1]), t=addrFromTopic(l.topics[2]), val=BigInt(l.data);
   txs.add(l.transactionHash); total += val;
   counts.set(f,(counts.get(f)||0)+1); counts.set(t,(counts.get(t)||0)+1);
   net.set(f,(net.get(f)||0n)-val); net.set(t,(net.get(t)||0n)+val);
   if (f==='0x0000000000000000000000000000000000000000') mint += val;
 }
 const topCount=[...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,12);
 const topNet=[...net.entries()].sort((a,b)=> (b[1]>a[1]?1:-1)).slice(0,8);
 const topOut=[...net.entries()].sort((a,b)=> (a[1]>b[1]?1:-1)).slice(0,8);
 console.log(JSON.stringify({latest:Number(latest), from:Number(from), logs:logs.length, txs:txs.size, uniqueAddresses:counts.size, mint:fmt(mint), moved:fmt(total), topCount, topNet:topNet.map(([a,v])=>[a,fmt(v)]), topOut:topOut.map(([a,v])=>[a,fmt(v)]), sampleFirst:logs.slice(0,3).map(l=>({block:parseInt(l.blockNumber), tx:l.transactionHash, from:addrFromTopic(l.topics[1]), to:addrFromTopic(l.topics[2]), amount:fmt(BigInt(l.data))})), sampleLast:logs.slice(-3).map(l=>({block:parseInt(l.blockNumber), tx:l.transactionHash, from:addrFromTopic(l.topics[1]), to:addrFromTopic(l.topics[2]), amount:fmt(BigInt(l.data))}))}, null, 2));
})().catch(e=>{console.error(e.stack || e); process.exit(1);});
