#!/usr/bin/env node

import { spawn } from "node:child_process";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";

const CONFIG = {
  url: process.env.DEBOT_URL || "https://debot.ai/?chain=solana",
  chromePort: Number(process.env.CHROME_DEBUG_PORT || 9222),
  chromeProfileDir:
    process.env.CHROME_DEBUG_PROFILE ||
    path.join(process.cwd(), ".debot-chrome-profile"),
  pollMs: Number(process.env.DEBOT_POLL_MS || 20_000),
  summaryMs: Number(process.env.DEBOT_SUMMARY_MS || 10 * 60_000),
  statePath:
    process.env.DEBOT_STATE_PATH ||
    path.join(process.cwd(), ".debot-monitor-state.json"),
  telegramToken: process.env.TELEGRAM_BOT_TOKEN || "",
  telegramChatId: process.env.TELEGRAM_CHAT_ID || "",
  dryRun: process.env.DEBOT_DRY_RUN === "1",
};

const DOG_GRADES = [
  ["金狗", /gold|金狗|黄金|金/i],
  ["银狗", /silver|银狗|白银|银/i],
  ["铜狗", /bronze|铜狗|青铜|铜/i],
];

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function requestJson(url, options = {}) {
  const response = await fetch(url, options);
  if (!response.ok) {
    throw new Error(`${response.status} ${response.statusText}: ${await response.text()}`);
  }
  return response.json();
}

async function loadState() {
  if (!existsSync(CONFIG.statePath)) {
    return { seen: {}, lastSummaryAt: 0 };
  }
  try {
    return JSON.parse(await readFile(CONFIG.statePath, "utf8"));
  } catch {
    return { seen: {}, lastSummaryAt: 0 };
  }
}

async function saveState(state) {
  await mkdir(path.dirname(CONFIG.statePath), { recursive: true });
  await writeFile(CONFIG.statePath, JSON.stringify(state, null, 2));
}

function chromeExecutable() {
  const candidates = [
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Google Chrome Canary.app/Contents/MacOS/Google Chrome Canary",
  ];
  const found = candidates.find((candidate) => existsSync(candidate));
  if (!found) throw new Error("Google Chrome executable not found.");
  return found;
}

async function ensureChrome() {
  try {
    await requestJson(`http://127.0.0.1:${CONFIG.chromePort}/json/version`);
    return;
  } catch {
    // Start an isolated Chrome profile so the monitor does not disturb the user's main browser.
  }

  await mkdir(CONFIG.chromeProfileDir, { recursive: true });
  const args = [
    `--remote-debugging-port=${CONFIG.chromePort}`,
    `--user-data-dir=${CONFIG.chromeProfileDir}`,
    "--no-first-run",
    "--no-default-browser-check",
    CONFIG.url,
  ];
  const child = spawn(chromeExecutable(), args, {
    detached: true,
    stdio: "ignore",
  });
  child.unref();

  for (let i = 0; i < 30; i += 1) {
    await sleep(1000);
    try {
      await requestJson(`http://127.0.0.1:${CONFIG.chromePort}/json/version`);
      return;
    } catch {
      // Keep waiting for Chrome's DevTools endpoint.
    }
  }
  throw new Error("Chrome DevTools endpoint did not start.");
}

async function getDebotTarget() {
  const targets = await requestJson(`http://127.0.0.1:${CONFIG.chromePort}/json`);
  let target = targets.find((item) => item.type === "page" && item.url.includes("debot.ai"));
  if (!target) {
    target = await requestJson(
      `http://127.0.0.1:${CONFIG.chromePort}/json/new?${encodeURIComponent(CONFIG.url)}`,
      { method: "PUT" },
    );
  }
  return target;
}

class CdpClient {
  constructor(wsUrl) {
    this.wsUrl = wsUrl;
    this.nextId = 1;
    this.pending = new Map();
  }

  async connect() {
    this.ws = new WebSocket(this.wsUrl);
    this.ws.addEventListener("message", (event) => {
      const payload = JSON.parse(event.data);
      if (!payload.id) return;
      const pending = this.pending.get(payload.id);
      if (!pending) return;
      this.pending.delete(payload.id);
      if (payload.error) pending.reject(new Error(payload.error.message));
      else pending.resolve(payload.result);
    });
    await new Promise((resolve, reject) => {
      this.ws.addEventListener("open", resolve, { once: true });
      this.ws.addEventListener("error", reject, { once: true });
    });
  }

  call(method, params = {}) {
    const id = this.nextId;
    this.nextId += 1;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      setTimeout(() => {
        if (!this.pending.has(id)) return;
        this.pending.delete(id);
        reject(new Error(`CDP timeout: ${method}`));
      }, 15_000);
    });
  }

  close() {
    this.ws?.close();
  }
}

const extractionScript = String.raw`
(() => {
  const tokenLinks = [...document.querySelectorAll('a[href*="/token/solana/306326_"]')];
  const byCa = new Map();
  for (const link of tokenLinks) {
    const href = new URL(link.getAttribute('href'), location.href).href;
    const match = href.match(/306326_([A-Za-z0-9]+)/);
    if (!match) continue;
    const ca = match[1];
    const card = link.closest('[class]') || link.parentElement;
    const text = (card?.innerText || link.innerText || '').replace(/\s+/g, ' ').trim();
    const project = (link.getAttribute('aria-label') || link.textContent || '')
      .replace(/^solana\s*/i, '')
      .trim() || ca.slice(0, 6);
    const imgAlts = [...(card || document).querySelectorAll('img')]
      .map((img) => `${img.alt || ''} ${img.getAttribute('src') || ''}`)
      .join(' ');
    byCa.set(ca, { project, ca, href, text, imgAlts });
  }
  return [...byCa.values()].slice(0, 80);
})()
`;

function classifySignal(item) {
  const haystack = `${item.text} ${item.imgAlts}`;
  for (const [grade, re] of DOG_GRADES) {
    if (re.test(haystack)) return grade;
  }
